'use strict';
(() => {
 const SITE='https://patchflow-audio-matsunaga.matsunagakoki.chatgpt.site';
 if(location.hostname==='koukimatsunaga02.github.io'){
  location.replace(SITE+'/account.html'+location.search+location.hash);return;
 }
 const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const paths={plus:'M12 5v14M5 12h14',folder:'M3 7V4h6l3 3h9v13H3z',grid:'M4 4h6v6H4zM14 4h6v6h-6zM4 14h6v6H4zM14 14h6v6h-6z',list:'M8 6h12M8 12h12M8 18h12M4 6h.01M4 12h.01M4 18h.01',search:'M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14ZM15 15l6 6',close:'M6 6l12 12M18 6 6 18',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v2M12 20v2M2 12h2M20 12h2M5 5l1 1M18 18l1 1M5 19l1-1M18 6l1-1',moon:'M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11',arrow:'M5 12h14M14 7l5 5-5 5',lock:'M7 10V7a5 5 0 0 1 10 0v3M5 10h14v11H5zM12 14v3',share:'M12 15V3M7 8l5-5 5 5M5 13v7h14v-7',users:'M9 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM2 21v-2a6 6 0 0 1 12 0v2M17 5a4 4 0 0 1 0 8M18 16a5 5 0 0 1 4 5',upload:'M12 16V4M7 9l5-5 5 5M4 17v4h16v-4',copy:'M8 8h12v13H8zM4 16H3V3h12v1',edit:'m14 4 6 6M4 20l4-1L21 6l-4-4L4 15z',trash:'M4 7h16M9 7V4h6v3M6 7l1 14h10l1-14M10 11v6M14 11v6',restore:'M4 4v6h6M4 10a8 8 0 1 1 1 9M12 7v5l3 2',cable:'M3 8h5v8H3zM8 12h8M16 8h5v8h-5zM5 5v3M19 16v3',check:'M4 12l5 5L20 6',logout:'M9 4H4v16h5M9 12h12M16 7l5 5-5 5',refresh:'M20 4v6h-6M20 10a8 8 0 1 0-1 9',sso:'M5 8h6v6H5zM13 3h6v6h-6zM13 15h6v6h-6zM11 11h3M11 11v7h2'};
 const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.folder}"/></svg>`;
 const validId=id=>typeof id==='string'&&/^[a-f0-9]{32}$/.test(id);
 let user=null,auth={},projects=[],inTrash=false,view='grid',search='',visibility='all',loading=false,loadSequence=0,banner=null,toastTimer=null,pendingBusy=false;
 try{view=localStorage.getItem('patchflow-account-view')==='list'?'list':'grid'}catch{}
 function applyTheme(theme){document.documentElement.dataset.theme=theme==='dark'?'dark':'light';$('#accounttheme').innerHTML=icon(theme==='dark'?'sun':'moon');$('#accounttheme').setAttribute('aria-label',theme==='dark'?'ライトモードにする':'ダークモードにする');try{localStorage.setItem('patchflow-theme',theme)}catch{}}
 let theme='light';try{theme=localStorage.getItem('patchflow-theme')||'light'}catch{}applyTheme(theme);$('#accounttheme').onclick=()=>applyTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');
 function authLink(value,signout=false){try{let u=new URL(value,location.href),origin=location.origin;return u.origin===origin&&u.pathname===(signout?'/signout-with-chatgpt':'/signin-with-chatgpt')?u.href:null}catch{return null}}
 function editorLink(value,id){try{let u=new URL(value||'editor.html#cloud='+id,location.href);return u.origin===location.origin&&u.pathname.endsWith('/editor.html')?u.href:new URL('editor.html#cloud='+id,location.href).href}catch{return new URL('editor.html#cloud='+id,location.href).href}}
 function shareLink(value){let u=new URL(value,location.href),allowed=u.origin===location.origin||u.origin==='https://koukimatsunaga02.github.io'||u.origin===SITE;if(!allowed||!(/\/(?:patchflow\/)?(?:view|editor)\.html$/.test(u.pathname)))throw Error('共有リンクを確認できませんでした。もう一度お試しください。');return u.href}
 async function api(path,options={}){let headers={Accept:'application/json',...(options.headers||{})};if(options.method&&options.method!=='GET'){headers['Content-Type']='application/json';headers['X-Patchflow-Request']='account'}let r=await fetch('/api/account'+path,{...options,headers,credentials:'same-origin',cache:'no-store'}),result;try{result=await r.json()}catch{throw Error('ワークスペースに接続できませんでした。時間をおいて再度お試しください。')}if(!r.ok){let error=Error(typeof result.error==='string'?result.error.slice(0,350):r.status===401?'ログインの有効期限が切れました。もう一度ログインしてください。':'操作を完了できませんでした。');error.status=r.status;throw error}return result}
 function pendingKey(){return 'patchflow-pending-import'}
 function storePending(){let transfer=/^#import=([a-f0-9]{32})\.([a-f0-9]{64})$/.exec(location.hash),open=/^#open=([a-f0-9]{32})$/.exec(location.hash);if(!transfer&&!open)return;try{if(transfer)sessionStorage.setItem(pendingKey(),JSON.stringify({id:transfer[1],token:transfer[2]}));if(open)sessionStorage.setItem('patchflow-pending-open',open[1]);history.replaceState(null,'',location.pathname+location.search)}catch{banner={error:true,title:'プロジェクトを引き継げませんでした',text:'このブラウザで一時保存が利用できません。ログイン後、保存元のJSONファイルを読み込んでください。'}}}
 function getPending(){try{let value=JSON.parse(sessionStorage.getItem(pendingKey())||'null');return value&&validId(value.id)&&/^[a-f0-9]{64}$/.test(value.token)?value:null}catch{return null}}
 function pendingOpen(){try{let id=sessionStorage.getItem('patchflow-pending-open');return validId(id)?id:null}catch{return null}}
 function clearPending(){try{sessionStorage.removeItem(pendingKey());sessionStorage.removeItem('patchflow-pending-open')}catch{}}
 storePending();
 function toast(text,undo){clearTimeout(toastTimer);let el=$('#accounttoast');el.replaceChildren();let span=document.createElement('span');span.textContent=text;el.append(span);if(undo){let button=document.createElement('button');button.textContent='元に戻す';button.onclick=async()=>{button.disabled=true;try{await undo();el.hidden=true}catch(e){span.textContent=e.message;button.disabled=false}};el.append(button)}el.hidden=false;toastTimer=setTimeout(()=>{el.hidden=true},undo?11000:5000)}
 function profile(){let root=$('#accountprofile');if(!user){root.replaceChildren();return}let name=user.name||user.email||'ユーザー';root.innerHTML=`<details class="profile-menu"><summary aria-label="アカウントメニュー"><span class="avatar">${esc([...name][0]||'P')}</span><span class="profile-name">${esc(name)}</span></summary><div class="profile-popover"><strong>${esc(name)}</strong><p>${esc(user.email||'')}</p><a id="accountsignout" target="_top">${icon('logout')}ログアウト</a></div></details>`;let out=authLink(auth.signOutUrl,true);if(out)$('#accountsignout').href=out;else $('#accountsignout').remove()}
 function signinVisual(){return `<div class="signin-visual" aria-label="DJミキサーからスピーカーへ、3mと5mのケーブルを延長して接続する配線図"><div class="visual-topline"><span>LIVE SESSION / EXAMPLE</span><b>PROJECT PREVIEW</b></div><svg class="visual-diagram" viewBox="0 0 440 300" role="img" aria-label="DJM-A9、延長ケーブル、DBR12の配線例"><g fill="var(--raised)" stroke="var(--line)"><rect x="15" y="43" width="150" height="218" rx="4"/><rect x="283" y="43" width="142" height="218" rx="4"/></g><g fill="var(--muted)" font-family="Arial,sans-serif" font-size="9"><text x="28" y="65">Pioneer DJ</text><text x="297" y="65">YAMAHA</text></g><g fill="var(--ink)" font-family="Arial,sans-serif" font-size="12"><text x="28" y="84">DJM-A9</text><text x="297" y="84">DBR12 / MAIN L</text></g><image href="assets/djm.png" x="32" y="103" width="115" height="114"/><image href="assets/dbr.jpg" x="304" y="101" width="102" height="121"/><path d="M165 235H283" stroke="var(--accent)" stroke-width="2.3" fill="none"/><g fill="var(--raised)" stroke="var(--accent)" stroke-width="1.5"><circle cx="165" cy="235" r="4"/><circle cx="209" cy="235" r="5"/><circle cx="283" cy="235" r="4"/></g><g fill="var(--surface)" stroke="var(--line)"><rect x="170" y="207" width="32" height="20" rx="3"/><rect x="232" y="207" width="32" height="20" rx="3"/></g><g fill="var(--ink)" font-family="Arial,sans-serif" font-size="10" text-anchor="middle"><text x="186" y="221">3m</text><text x="248" y="221">5m</text></g><g font-family="Arial,sans-serif" font-size="7" fill="var(--muted)"><text x="87" y="247">MASTER 1 L</text><text x="299" y="247">INPUT 1</text></g><text x="15" y="20" font-family="monospace" font-size="8" fill="var(--muted)">01 / AUDIO ROUTING</text></svg><div class="visual-note"><span>2 CABLES / 8m TOTAL</span><span>XLR → XLR</span></div><p class="visual-caption">配線も、ケーブルの長さも、現場のメモも。<br>ひとつのプロジェクトにまとめて。</p></div>`}
 function renderSignin(error){$('#headerlabel').textContent='ログイン / ワークスペース';profile();let signIn=authLink(auth.signInUrl),hasPending=Boolean(getPending()||pendingOpen());$('#accountmain').innerHTML=`<section class="signin-layout"><div class="signin-copy"><div class="eyebrow"><span class="index">01</span> YOUR SIGNAL WORKSPACE</div><h1>配線の続きを、<br>どの現場からでも。</h1><p>音響と映像の構成を、自分のワークスペースへ。ログインするとプロジェクトを保存して、別の端末からも続きを編集できます。</p><div class="signin-card">${signIn?`<a id="accountsignin" class="action primary" target="_top" data-oai-siwc-button>${icon('sso')}ChatGPTで続ける ${icon('arrow')}</a>`:`<button id="authretry" class="primary">${icon('refresh')}接続を再試行</button>`}<p>ChatGPTのアカウントでログインします。<br>PATCHFLOW用のパスワードを作る必要はありません。</p>${hasPending?'<p>編集中のプロジェクトは、ログイン後に引き継ぎます。</p>':''}${error?`<p class="dialog-status error" role="alert">${esc(error)}</p>`:''}<a class="guest-link" href="editor.html">ログインせずにエディターを使う ${icon('arrow')}</a></div><ul class="signin-benefits"><li>${icon('lock')}新しいプロジェクトは自分だけに公開</li><li>${icon('share')}必要なときだけ、閲覧・編集リンクで共有</li><li>${icon('check')}ゲストで作ったJSONも読み込み可能</li></ul></div>${signinVisual()}</section><footer class="account-foot"><span>PATCHFLOW / SIGNAL DESIGN STUDIO</span><span>AUDIO + VIDEO, CONNECTED.</span></footer>`;if(signIn)$('#accountsignin').href=signIn;$('#authretry')?.addEventListener('click',boot);$('#accountmain').setAttribute('aria-busy','false')}
 function bannerMarkup(){if(!banner)return '';return `<div class="workspace-banner ${banner.error?'error':''}" role="${banner.error?'alert':'status'}"><div><strong>${esc(banner.title)}</strong><p>${esc(banner.text)}</p></div>${getPending()||pendingOpen()?'<button id="retrypending">もう一度引き継ぐ</button><button id="dismisspending">あとで読み込む</button>':(banner.loadError?'<button id="retryprojectload">再読み込み</button>':'')+'<button id="dismissbanner" aria-label="通知を閉じる">'+icon('close')+'</button>'}</div>`}
 function renderWorkspace(){profile();$('#headerlabel').textContent='自分のプロジェクト';$('#accountmain').innerHTML=`<section class="workspace-shell"><div class="workspace-heading"><div><div class="eyebrow">YOUR WORKSPACE / CLOUD PROJECTS</div><h1>プロジェクト</h1><p>音と映像の構成を、ここから。</p></div><div class="heading-actions"><button id="accountimport">${icon('upload')}JSONを読み込む</button><button id="accountnew" class="primary">${icon('plus')}新規プロジェクト</button></div></div><div id="workspacebanner">${bannerMarkup()}</div><div class="workspace-toolbar"><div class="workspace-tabs"><button id="activetab" aria-pressed="${!inTrash}">マイプロジェクト</button><button id="trashtab" aria-pressed="${inTrash}">${icon('trash')}ゴミ箱</button></div><div class="toolbar-filters"><label class="workspace-search">${icon('search')}<input id="accountsearch" aria-label="プロジェクトを検索" placeholder="プロジェクトを検索" value="${esc(search)}"></label><select id="accountfilter" aria-label="共有状態で絞り込む"><option value="all">すべての状態</option><option value="private">自分だけ</option><option value="link">リンクで共有中</option></select><div class="view-switch" aria-label="一覧の表示形式"><button data-view="grid" aria-pressed="${view==='grid'}" aria-label="グリッド表示">${icon('grid')}</button><button data-view="list" aria-pressed="${view==='list'}" aria-label="リスト表示">${icon('list')}</button></div></div></div><div id="projectresults" class="result-count" role="status"></div><div id="cloudprojects"></div><div class="workspace-bottom-note">${icon('lock')}<span>プロジェクトは自分だけに公開されます。「共有」からリンクを発行したプロジェクトは、リンクを知っている人が閲覧・編集できます。</span></div></section>`;$('#accountfilter').value=visibility;$('#accountnew').onclick=()=>projectNameDialog();$('#accountimport').onclick=()=>$('#accountfile').click();$('#accountsearch').oninput=e=>{search=e.target.value;renderCards()};$('#accountfilter').onchange=e=>{visibility=e.target.value;renderCards()};$('#activetab').onclick=()=>switchTab(false);$('#trashtab').onclick=()=>switchTab(true);for(let b of document.querySelectorAll('[data-view]'))b.onclick=()=>{view=b.dataset.view;try{localStorage.setItem('patchflow-account-view',view)}catch{}for(let x of document.querySelectorAll('[data-view]'))x.setAttribute('aria-pressed',String(x===b));renderCards()};bindBanner();renderCards();$('#accountmain').setAttribute('aria-busy','false')}
 function bindBanner(){$('#retryprojectload')?.addEventListener('click',loadProjects);$('#retrypending')?.addEventListener('click',handlePending);$('#dismisspending')?.addEventListener('click',()=>{clearPending();banner=null;renderWorkspace()});$('#dismissbanner')?.addEventListener('click',()=>{banner=null;$('#workspacebanner').replaceChildren()})}
 function switchTab(trash){if(inTrash===trash)return;inTrash=trash;search='';renderWorkspace();loadProjects()}
 function dateLabel(value){let d=new Date(value);return Number.isNaN(d.getTime())?'保存済み':new Intl.DateTimeFormat('ja-JP',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(d)+' 更新'}
 function previewMarkup(project){let n=Math.max(0,Number(project.nodeCount)||0),c=Math.max(0,Number(project.cableCount)||0),hash=[...project.id].reduce((a,x)=>a+x.charCodeAt(0),0),shift=hash%3*6;if(!n)return `<svg viewBox="0 0 300 160" aria-hidden="true"><rect x="123" y="50" width="54" height="54" rx="4" fill="var(--surface)" stroke="var(--line)"/><path d="M150 68v18M141 77h18" stroke="var(--muted)" stroke-width="1.5"/></svg>`;let card=(x,y,w=56,h=51)=>`<g fill="var(--surface)" stroke="var(--line)"><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="3"/><path d="M${x+8} ${y+10}h${w-16}M${x+8} ${y+16}h${Math.max(12,w-25)}" opacity=".8"/></g><rect x="${x+9}" y="${y+25}" width="${w-18}" height="${h-33}" rx="1" fill="var(--alt)"/>`;return `<svg viewBox="0 0 300 160" aria-hidden="true"><g stroke="var(--muted)" stroke-width="1.3" fill="none" opacity=".65"><path d="M74 ${50+shift}C110 ${50+shift} 105 77 137 77M74 ${111-shift}C110 ${111-shift} 108 89 137 89M193 81H226"/>${c>3?'<path d="M165 109V132H248V106"/>':''}</g><path d="M193 81H226" stroke="var(--accent)" stroke-width="1.6"/><circle cx="211" cy="81" r="3" stroke="var(--accent)" fill="var(--surface)"/>${card(23,24+shift,51,48)}${card(23,87-shift,51,48)}${card(137,54,56,55)}${card(226,56,51,51)}<g fill="var(--accent)"><circle cx="74" cy="${50+shift}" r="2"/><circle cx="137" cy="77" r="2"/><circle cx="193" cy="81" r="2"/><circle cx="226" cy="81" r="2"/></g></svg>`}
 function projectCard(p,index){let id=validId(p.id)?p.id:'',url=editorLink(p.editorUrl,id),shared=p.visibility==='link',count=Math.max(0,Number(p.nodeCount)||0),cables=Math.max(0,Number(p.cableCount)||0),previewOpen=inTrash?'<div class="project-preview">':`<a class="project-preview" href="${esc(url)}" aria-label="${esc(p.title||'無題のプロジェクト')}を開く">`,previewClose=inTrash?'</div>':'</a>',titleOpen=inTrash?'<span class="project-title">':`<a class="project-title" href="${esc(url)}">`,titleClose=inTrash?'</span>':'</a>';return `<article class="project-card" data-project="${esc(id)}">${previewOpen}<span class="project-seq">PATCH / ${String(index+1).padStart(2,'0')}</span>${previewMarkup(p)}${previewClose}<div class="project-card-info"><div class="project-title-row">${titleOpen}${esc(p.title||'無題のプロジェクト')}${titleClose}<details class="card-menu"><summary aria-label="${esc(p.title||'プロジェクト')}の操作">•••</summary><div class="card-menu-panel">${inTrash?`<button data-action="restore">${icon('restore')}プロジェクトを復元</button>`:`<button data-action="rename">${icon('edit')}名前を変更</button><button data-action="duplicate">${icon('copy')}複製する</button><button data-action="share">${icon('share')}共有する</button><hr><button data-action="archive" class="danger">${icon('trash')}ゴミ箱へ移動</button>`}</div></details></div><div class="project-meta"><span>${icon('grid')}${count} 機材</span><span>${icon('cable')}${cables} ケーブル</span></div><div class="project-card-footer"><small>${esc(dateLabel(p.updatedAt))}</small>${inTrash?`<button class="card-restore" data-action="restore">${icon('restore')}復元</button>`:`<span class="project-privacy ${shared?'shared':''}">${icon(shared?'share':'lock')}${shared?'リンクで共有中':'自分だけ'}</span>`}</div></div></article>`}
 function renderCards(){let root=$('#cloudprojects');if(!root)return;root.className=view==='grid'?'project-grid':'project-list';if(loading){$('#projectresults').textContent='読み込んでいます';root.innerHTML='<div class="skeleton-card"></div>'.repeat(view==='grid'?3:2);return}let q=search.trim().toLocaleLowerCase('ja-JP'),shown=projects.filter(p=>(!q||String(p.title||'').toLocaleLowerCase('ja-JP').includes(q))&&(visibility==='all'||p.visibility===visibility));$('#projectresults').textContent=`${shown.length} PROJECT${shown.length===1?'':'S'}${inTrash?' / TRASH':''}`;if(!shown.length){root.className='';let filtered=Boolean(q||visibility!=='all');root.innerHTML=`<div class="empty-workspace"><div class="empty-icon">${icon(filtered?'search':inTrash?'trash':'folder')}</div><h2>${filtered?'該当するプロジェクトがありません':inTrash?'ゴミ箱は空です':'最初のプロジェクトを作ろう。'}</h2><p>${filtered?'検索する名前や共有状態を変えてみてください。':inTrash?'移動したプロジェクトはここから復元できます。':'空のキャンバスから音響・映像の構成を作成できます。ゲストで作った構成はJSONから読み込めます。'}</p><div class="empty-actions">${filtered?'<button id="clearprojectfilters">条件をリセット</button>':inTrash?'<button id="backtoprojects">マイプロジェクトへ</button>':`<button id="emptynew" class="primary">${icon('plus')}新規プロジェクト</button><button id="emptyimport">${icon('upload')}JSONを読み込む</button>`}</div></div>`;$('#clearprojectfilters')?.addEventListener('click',()=>{search='';visibility='all';$('#accountsearch').value='';$('#accountfilter').value='all';renderCards()});$('#backtoprojects')?.addEventListener('click',()=>switchTab(false));$('#emptynew')?.addEventListener('click',()=>projectNameDialog());$('#emptyimport')?.addEventListener('click',()=>$('#accountfile').click());return}root.innerHTML=shown.map(projectCard).join('');for(let card of root.querySelectorAll('[data-project]'))for(let b of card.querySelectorAll('[data-action]'))b.onclick=()=>{card.querySelector('.card-menu').open=false;let p=projects.find(p=>p.id===card.dataset.project);if(p)projectAction(b.dataset.action,p,b)}}
 async function loadProjects(){let sequence=++loadSequence;loading=true;renderCards();try{let result=await api('/projects'+(inTrash?'?trash=1':''));if(sequence!==loadSequence)return;projects=Array.isArray(result.projects)?result.projects.filter(p=>validId(p.id)):[];projects.sort((a,b)=>Number(new Date(b.updatedAt))-Number(new Date(a.updatedAt)));if(banner?.loadError){banner=null;$('#workspacebanner')?.replaceChildren()}}catch(e){if(sequence!==loadSequence)return;projects=[];banner={error:true,loadError:true,title:'プロジェクトを読み込めませんでした',text:e.message};$('#workspacebanner').innerHTML=bannerMarkup();bindBanner()}finally{if(sequence===loadSequence){loading=false;renderCards()}}}
 function dialog(title,body){let d=document.createElement('dialog');d.innerHTML=`<div class="dialog-header"><div><div class="eyebrow">PATCHFLOW / WORKSPACE</div><h2>${esc(title)}</h2></div><button class="icon-button" data-dialog-close aria-label="閉じる">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;d.querySelector('[data-dialog-close]').onclick=()=>d.close();d.addEventListener('close',()=>d.remove());document.body.append(d);d.showModal();return d}
 function projectNameDialog(project){let rename=Boolean(project),d=dialog(rename?'プロジェクト名を変更':'新しいプロジェクト',`<p>${rename?'現場で見つけやすい名前を付けておこう。':'音響と映像を、ひとつのキャンバスで。新しいプロジェクトは自分だけに公開されます。'}</p><form id="projectnameform"><label>プロジェクト名<input id="projectname" aria-label="プロジェクト名" maxlength="100" required placeholder="例：週末ライブ / 配信スタジオ"></label><div class="dialog-status" role="status"></div><div class="dialog-footer"><button type="button" data-cancel>キャンセル</button><button class="primary" type="submit">${rename?'名前を保存':'作成して開く'} ${icon('arrow')}</button></div></form>`),form=d.querySelector('form'),field=d.querySelector('input'),status=d.querySelector('[role=status]'),submit=form.querySelector('[type=submit]');field.value=project?.title||'';d.querySelector('[data-cancel]').onclick=()=>d.close();form.onsubmit=async e=>{e.preventDefault();let title=field.value.trim();if(!title){status.textContent='プロジェクト名を入力してください。';field.focus();return}submit.disabled=true;status.classList.remove('error');status.textContent=rename?'名前を保存しています…':'プロジェクトを作成しています…';try{if(rename){await api('/projects/'+project.id,{method:'PATCH',body:JSON.stringify({ops:[{collection:'project',action:'set',fields:{title}}]})});d.close();await loadProjects();toast('プロジェクト名を変更しました')}else{let result=await api('/projects',{method:'POST',body:JSON.stringify({title})});if(!validId(result.id))throw Error('作成されたプロジェクトを確認できませんでした。');location.assign(editorLink(result.editorUrl,result.id))}}catch(err){status.textContent=err.message;status.classList.add('error');submit.disabled=false}};field.focus()}
 async function projectAction(action,p,button){if(action==='rename'){projectNameDialog(p);return}if(action==='share'){shareDialog(p);return}button.disabled=true;try{if(action==='duplicate'){let r=await api('/projects/'+p.id+'/duplicate',{method:'POST',body:'{}'});await loadProjects();toast('「'+(p.title||'プロジェクト')+'」を複製しました');if(r.id&&!projects.some(p=>p.id===r.id))await loadProjects()}else if(action==='archive'){await api('/projects/'+p.id+'/archive',{method:'POST',body:'{}'});await loadProjects();toast('ゴミ箱へ移動しました',async()=>{await api('/projects/'+p.id+'/restore',{method:'POST',body:'{}'});await loadProjects()})}else if(action==='restore'){await api('/projects/'+p.id+'/restore',{method:'POST',body:'{}'});await loadProjects();toast('プロジェクトを復元しました')}}catch(e){toast(e.message);button.disabled=false}}
 function shareDialog(project){let d=dialog('プロジェクトを共有',`<p>「${esc(project.title||'無題のプロジェクト')}」の共有リンクを発行します。リンクを知っている相手がアクセスできるようになります。</p><div class="sharing-buttons"><button data-kind="view">${icon('share')}<span><b>閲覧リンク</b><small>確認だけしてほしい相手に。<br>同じURLで最新の配線図を表示。</small></span></button><button data-kind="edit">${icon('users')}<span><b>編集リンク</b><small>一緒に構成を作る相手に。<br>カーソルと選択状況も共有。</small></span></button></div><div class="share-link-box" hidden><label><span data-linklabel>共有リンク</span><div class="share-link-row"><input readonly aria-label="共有リンク"><button data-copy>${icon('copy')}コピー</button></div></label><p data-linknote></p></div><p class="dialog-status" role="status"></p><div class="share-revoke"><p>共有を停止すると、発行済みの<br>閲覧・編集リンクからアクセスできなくなります。</p><button data-revoke class="danger">共有を停止</button></div><div class="revoke-confirm" hidden><p>このプロジェクトの共有リンクを停止します。再び共有する場合は、新しいリンクを発行してください。</p><div><button data-cancelrevoke>キャンセル</button><button data-confirmrevoke class="danger">停止する</button></div></div>`),status=d.querySelector('[role=status]'),box=d.querySelector('.share-link-box'),input=d.querySelector('input'),revokeButton=d.querySelector('[data-revoke]');revokeButton.disabled=project.visibility!=='link';for(let b of d.querySelectorAll('[data-kind]'))b.onclick=async()=>{let buttons=d.querySelectorAll('[data-kind]');for(let x of buttons)x.disabled=true;status.classList.remove('error');status.textContent='リンクを発行しています…';try{let r=await api('/projects/'+project.id+'/share',{method:'POST',body:JSON.stringify({kind:b.dataset.kind})});input.value=shareLink(r.url);d.querySelector('[data-linklabel]').textContent=b.dataset.kind==='edit'?'編集リンク':'閲覧リンク';d.querySelector('[data-linknote]').textContent=b.dataset.kind==='edit'?'このリンクを知っている相手は、プロジェクトの機材・配線・コメントを編集できます。':'このリンクを知っている相手は閲覧できます。編集はできません。先方がリロードすると最新の保存内容を表示します。';box.hidden=false;status.textContent='リンクを発行しました。相手にコピーして送ってください。';project.visibility='link';revokeButton.disabled=false;renderCards()}catch(e){status.textContent=e.message;status.classList.add('error')}finally{for(let x of buttons)x.disabled=false}};d.querySelector('[data-copy]').onclick=async()=>{try{await navigator.clipboard.writeText(input.value);status.textContent='リンクをコピーしました';status.classList.remove('error')}catch{input.focus();input.select();status.textContent='リンクを選択しました。コピーして送ってください。'}};d.querySelector('[data-revoke]').onclick=()=>{d.querySelector('.revoke-confirm').hidden=false};d.querySelector('[data-cancelrevoke]').onclick=()=>{d.querySelector('.revoke-confirm').hidden=true};let confirmRevoke=d.querySelector('[data-confirmrevoke]');confirmRevoke.onclick=async()=>{confirmRevoke.disabled=true;status.classList.remove('error');status.textContent='共有を停止しています…';try{await api('/projects/'+project.id+'/unshare',{method:'POST',body:'{}'});project.visibility='private';revokeButton.disabled=true;renderCards();box.hidden=true;d.querySelector('.revoke-confirm').hidden=true;status.textContent='共有を停止しました。このプロジェクトは自分だけが開けます。'}catch(err){status.textContent=err.message;status.classList.add('error')}finally{confirmRevoke.disabled=false}}}
 async function importFile(file){if(!file)return;if(file.size>30000000){toast('ファイルが大きすぎます。30MB以下のJSONを選んでください。');return}let parsed,items;try{parsed=JSON.parse(await file.text());items=parsed?.kind==='patchflow-project-library'&&Array.isArray(parsed.projects)?parsed.projects.map(p=>p.data):[parsed];if(!items.length||items.length>100||items.some(p=>!p||p.version!==1||typeof p.title!=='string'||!Array.isArray(p.nodes)||!Array.isArray(p.edges)))throw Error('invalid')}catch{toast('PATCHFLOWのプロジェクトJSONを選んでください。');return}let d=dialog('JSONからプロジェクトを読み込む',`<p>${items.length}件のプロジェクトを、自分だけに公開するコピーとして読み込みます。元のファイルは変更されません。</p><ul class="import-results">${items.map(p=>`<li><b>${esc(p.title||'無題のプロジェクト')}</b><br>${p.nodes.length} 機材 / ${p.edges.length} 経路</li>`).join('')}</ul><p class="dialog-status" role="status"></p><div class="dialog-footer"><button data-cancel>キャンセル</button><button data-import class="primary">${icon('upload')}読み込む</button></div>`),status=d.querySelector('[role=status]');d.querySelector('[data-cancel]').onclick=()=>d.close();d.querySelector('[data-import]').onclick=async()=>{for(let b of d.querySelectorAll('button'))b.disabled=true;let done=0;try{for(let data of items){status.textContent=`${done+1} / ${items.length} 件を読み込んでいます…`;await api('/projects',{method:'POST',body:JSON.stringify({data})});done++}d.close();inTrash=false;search='';visibility='all';renderWorkspace();await loadProjects();toast(done+'件のプロジェクトを読み込みました')}catch(e){status.classList.add('error');status.textContent=`${done}件を読み込み済みです。${done+1}件目は読み込めませんでした。${e.message}`;d.querySelector('[data-cancel]').disabled=false;d.querySelector('[data-dialog-close]').disabled=false;d.querySelector('[data-cancel]').textContent='閉じる';await loadProjects()}}}
 $('#accountfile').onchange=async e=>{let file=e.target.files?.[0];e.target.value='';await importFile(file)};
 async function handlePending(){if(pendingBusy)return false;let pending=getPending(),open=pendingOpen();if(!user||!pending&&!open)return false;pendingBusy=true;banner={title:'プロジェクトを引き継いでいます',text:'保存された構成を確認しています。'};if($('#workspacebanner'))$('#workspacebanner').innerHTML=bannerMarkup();try{let r;if(pending)r=await api('/projects/claim',{method:'POST',body:JSON.stringify(pending)});else{r=await api('/projects/'+open);r.id=open}if(!validId(r.id))throw Error('プロジェクトを確認できませんでした。');let url=editorLink(r.editorUrl,r.id);clearPending();location.assign(url);return true}catch(e){banner={error:true,title:'プロジェクトを引き継げませんでした',text:e.message+' 保存元からもう一度開くか、JSONファイルを読み込んでください。'};if($('#workspacebanner')){$('#workspacebanner').innerHTML=bannerMarkup();bindBanner()}return false}finally{pendingBusy=false}}
 async function boot(){$('#accountmain').setAttribute('aria-busy','true');try{auth=await api('');user=auth.user||null;if(!user){renderSignin(banner?.text);return}renderWorkspace();if(await handlePending())return;await loadProjects()}catch(e){if(!user){auth={signInUrl:'/signin-with-chatgpt?return_to=%2Faccount.html'};renderSignin(e.message)}else{banner={error:true,title:'ワークスペースに接続できませんでした',text:e.message};renderWorkspace()}}finally{$('#accountmain').setAttribute('aria-busy','false')}}
 document.addEventListener('click',e=>{for(let menu of document.querySelectorAll('details[open]'))if(!menu.contains(e.target))menu.open=false});
 window.addEventListener('online',()=>{if(user)loadProjects()});
 boot();
})();
